from pathlib import Path
p=Path('dist/app.js');s=p.read_text()
def replace_fn(name,code):
 global s
 start=s.index('function '+name+'(')
 end=s.find('\nfunction ',start+1)
 if end<0:raise Exception(name)
 s=s[:start]+code.rstrip()+'\n'+s[end:]
s=s.replace("let recipes=[],translations={},tags={},icons={},addons=[],pack={},mods=[],report={},stress={},engine", "let recipes=[],translations={},tags={},icons={},addons=[],pack={},mods=[],report={},stress={},catalogMods=[],iconReport={},engine")
s=s.replace("view='home',recipeQuery='',recipeScope='featured'", "view='home',recipeQuery='',recipeScope='featured'")
s=s.replace("['home','⌂','Vista general']", "['home','⌂','Mesa de trabajo']")
s=s.replace("['recipes','▦','Recetario']", "['recipes','▦','Archivo de recetas']")
s=s.replace("['mods','◈','Explorar mods']", "['mods','◈','Biblioteca de mods']")
s=s.replace("'mods','report','stress'];", "'mods','report','stress','mods-catalog','icon-coverage'];")
s=s.replace("[recipes,translations,tags,icons,addons,pack,mods,report,stress]=data", "[recipes,translations,tags,icons,addons,pack,mods,report,stress,catalogMods,iconReport]=data")
replace_fn('icon', '''function icon(id){const resolved=id.startsWith('fluid:')?id.slice(6):id;const url=icons[resolved];return url?`<img class="item-icon" src="${esc(url)}" alt="" title="${esc(name(resolved))}" loading="lazy">`:`<span class="item-fallback" role="img" aria-label="Icono no disponible: ${esc(name(resolved))}" title="Icono no disponible para ${esc(name(resolved))}"><svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="m16 4 11 6v13l-11 6-11-6V10Z M5 10l11 6 11-6M16 16v13" stroke="currentColor" stroke-width="1.2"/><path d="m11 7 11 6v5" stroke="currentColor" stroke-width=".8"/></svg><small>?</small></span>`;}''')
replace_fn('pageTitle', '''function pageTitle(eyebrow,title,description,action=''){return `<div class="sheet-heading"><div class="sheet-code">BB / ATM10 — 8.1 <span>ARCHIVO DEL TALLER</span></div><div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${action}</div><div class="desk-ruler" aria-hidden="true"><span>0</span><span>10</span><span>20</span><span>30</span><span>40</span><span>50</span><span>60</span><span>70</span><span>80</span><span>90</span></div></div>`;}''')
replace_fn('homeView', '''function homeView(){const cur=currentPhase();const num=phases.indexOf(cur)+1;return `<div class="desk-welcome"><div><span class="eyebrow">ALL THE MODS 10 · TU MESA DE INGENIERÍA</span><h1>Las grandes ideas<br>empiezan sobre un plano.</h1></div><div class="desk-stamp">BRASSBOUND<br><strong>EDICIÓN 8.1</strong><br>CONSTRUIR · EXPLORAR · CONECTAR</div></div><section class="hero blueprint-sheet"><span class="paper-clip" aria-hidden="true"></span><div class="hero-copy"><div class="eyebrow">PROYECTO 001 / MECÁNICA</div><h2>Del primer giro<br>a tu gran <em>fábrica.</em></h2><p>El taller está listo. Elige un objetivo, despliega sus planos y reúne cada pieza. Tu mundo se construye a tu ritmo.</p><button class="btn btn-primary" data-phase="${cur.id}">${totalDone()?'Continuar mi proyecto':'Empezar con Create'} <span>↗</span></button></div><img class="hero-art" src="assets/workshop-blueprint.svg" alt="Plano técnico de una rueda hidráulica conectada a una prensa y una correa"><div class="blueprint-titleblock"><span>BB–001 / PLANTA DE INICIO</span><span>CREATE 6.0.10</span><span>ESC. ILUSTRATIVA</span></div></section><section class="stats-grid" aria-label="Estado de tu mesa"><div class="stat"><div class="stat-label">Proyecto Create</div><div class="stat-value">${percent()}<small>% completado</small></div><div class="mini-bar"><span style="width:${percent()}%"></span></div></div><div class="stat"><div class="stat-label">Objetivos del taller</div><div class="stat-value">${totalDone()}<small>/ ${totalTasks()}</small></div><small class="muted">Etapa ${String(num).padStart(2,'0')} · ${cur.name}</small></div><div class="stat"><div class="stat-label">Planos guardados</div><div class="stat-value">${String(state.plans.length).padStart(2,'0')}<small>proyectos</small></div><button class="btn btn-text" data-view="notes">Abrir bitácora ↗</button></div><div class="stat"><div class="stat-label">Piezas en el archivo</div><div class="stat-value">${fmt(recipes.length)}<small>recetas</small></div><small class="muted">Mecánica, tecnología, magia y recursos</small></div></section><section class="workbench-section"><div class="section-heading"><div><div class="eyebrow">01 / ELIGE TU SIGUIENTE PROYECTO</div><h2>Más de una forma de construir.</h2></div><button class="btn btn-text" data-view="mods">Todos los mods ↗</button></div><div class="discipline-grid">${disciplines.map((d,i)=>`<button class="discipline-card" data-discipline="${d.id}"><span class="discipline-index">0${i+1}</span><div class="discipline-icons">${d.items.filter(id=>icons[id]).slice(0,3).map(icon).join('')||'<span class="discipline-letter">'+d.mark+'</span>'}</div><small>${d.mods}</small><h3>${d.label}</h3><p>${d.description}</p><span class="discipline-link">Desplegar recetas <span>↗</span></span></button>`).join('')}</div></section><div class="dashboard-columns"><section><div class="section-heading"><div><div class="eyebrow">02 / TU PROYECTO ACTUAL</div><h2>El camino del ingeniero</h2></div><button class="btn btn-text" data-view="routes">Ver todas las rutas ↗</button></div><div class="panel route-preview">${phases.slice(0,4).map((p,i)=>`<div class="route-row ${p.id===cur.id?'current':''} ${completed(p)===p.tasks.length?'done':''}"><span class="step-number">${completed(p)===p.tasks.length?'✓':String(i+1).padStart(2,'0')}</span><div class="row-copy"><h4>${p.name}</h4><p>${p.subtitle}</p></div>${p.id===cur.id?'<span class="badge gold">SIGUIENTE</span>':'<span class="row-arrow">↗</span>'}<button data-phase="${p.id}" aria-label="Abrir etapa ${p.name}"></button></div>`).join('')}</div></section><section class="pinned-note"><span class="note-pin" aria-hidden="true"></span><small>NOTA DEL INGENIERO</small><h3>Una máquina.<br>Muchas posibilidades.</h3><p>Empieza con una necesidad: guardar, generar energía, conseguir recursos o automatizar. Después elige el mod que la resuelva.</p><button class="btn btn-text" data-all-routes>Explorar otras rutas →</button><span class="note-signature">— Un engranaje a la vez.</span></section></div>${storageError?'<p class="server-note">El almacenamiento local no está disponible. Exporta tu avance desde Mi bitácora.</p>':''}`;}''')
# Add category information shared by home, recipe tabs and mod shelf.
pos=s.index('function name(')
s=s[:pos]+'''const disciplines=[
{id:'create',label:'Mecánica & movimiento',mods:'CREATE + ADDONS',mark:'⚙',description:'Engranajes, fábricas, trenes y todo lo que gira.',items:['create:mechanical_press','create:water_wheel','create:precision_mechanism']},
{id:'tech',label:'Tecnología & energía',mods:'MEKANISM · AE2 · POWAH',mark:'ϟ',description:'Máquinas, electricidad y redes que conectan tu base.',items:['mekanism:metallurgic_infuser','ae2:controller','powah:energizing_orb']},
{id:'magic',label:'Magia & descubrimientos',mods:'ARS NOUVEAU · MYSTICAL AGRICULTURE',mark:'✧',description:'Hechizos, esencia y otras maneras de automatizar.',items:['ars_nouveau:novice_spell_book','mysticalagriculture:inferium_essence','ars_nouveau:source_gem']},
{id:'resources',label:'Recursos & almacén',mods:'STORAGE · BACKPACKS · BEES',mark:'▤',description:'Dale un lugar a cada pieza y una salida a cada fábrica.',items:['functionalstorage:oak_1','sophisticatedbackpacks:backpack','productivebees:advanced_oak_beehive']}
];
function categoryFor(modId){if(addons.some(a=>a.modId===modId))return 'create';const meta=catalogMods.find(m=>m.modId===modId);if(meta){if(meta.category==='storage')return 'resources';return meta.category;}return 'other';}
function catalogName(modId){return addons.find(a=>a.modId===modId)?.name||catalogMods.find(a=>a.modId===modId)?.name||(modId==='minecraft'?'Minecraft':modId==='atm10'?'Especiales de ATM10':modId);}
function featuredRecipes(){const list=[...featured,...disciplines.flatMap(d=>d.items)];return [...new Set(list)].map(id=>engine.choose(id)).filter(Boolean);}
''' + s[pos:]
replace_fn('filteredRecipes', '''function filteredRecipes(){let list=recipes.filter(r=>r.output?.id);if(recipeScope==='featured')list=featuredRecipes();else if(['create','tech','magic','resources'].includes(recipeScope))list=list.filter(r=>categoryFor(r.source.modId)===recipeScope);else if(recipeScope==='pack')list=list.filter(r=>r.id.startsWith('atm-guide:'));if(recipeMod!=='all')list=list.filter(r=>r.source.modId===recipeMod);const q=recipeQuery.toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g,'');if(q)list=list.filter(r=>(name(r.output.id)+' '+engName(r.output.id)+' '+r.output.id+' '+r.id+' '+process(r.type)).toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').includes(q));if(recipeScope!=='featured')list.sort((a,b)=>{const aPriority=featured.includes(a.output.id)||disciplines.some(d=>d.items.includes(a.output.id));const bPriority=featured.includes(b.output.id)||disciplines.some(d=>d.items.includes(b.output.id));return Number(bPriority)-Number(aPriority)||name(a.output.id).localeCompare(name(b.output.id),'es');});return list;}''')
replace_fn('recipesView', '''function recipesView(){const list=filteredRecipes(),size=24;recipePage=Math.min(recipePage,Math.max(0,Math.ceil(list.length/size)-1));const catalog=[...addons,...catalogMods].filter((m,i,all)=>all.findIndex(x=>x.modId===m.modId)===i);return pageTitle('ARCHIVO 02 / PIEZAS Y PROCESOS','Cada pieza tiene su plano.','Despliega una receta, reconoce sus materiales y prepara tu siguiente proyecto. Mecánica, tecnología, magia y recursos sobre la misma mesa.')+`<div class="catalog-desk"><div class="catalog-toolbar"><div class="search-field"><span aria-hidden="true">⌕</span><input id="recipe-search" type="search" placeholder="Buscar una pieza, máquina o material…" value="${esc(recipeQuery)}" aria-label="Buscar recetas"><kbd>/</kbd></div><select id="recipe-mod" aria-label="Filtrar por mod"><option value="all">Todo el taller</option>${catalog.map(m=>`<option value="${m.modId}" ${recipeMod===m.modId?'selected':''}>${esc(m.name)}</option>`).join('')}<option value="minecraft" ${recipeMod==='minecraft'?'selected':''}>Minecraft</option><option value="atm10" ${recipeMod==='atm10'?'selected':''}>ATM10 · recetas especiales</option></select></div><div class="folder-tabs">${[['featured','Selección del taller'],['create','Mecánica'],['tech','Tecnología'],['magic','Magia'],['resources','Recursos'],['all','Todo']].map(([id,n])=>`<button class="folder-tab ${recipeScope===id?'active':''}" data-recipe-scope="${id}">${n}</button>`).join('')}</div><div class="archive-heading"><span><b>${fmt(list.length)}</b> planos disponibles</span><span>ATM10 8.1 <i>·</i> CATÁLOGO VERIFICABLE</span></div><div id="recipe-results">${list.length?`<div class="recipe-grid">${list.slice(recipePage*size,(recipePage+1)*size).map((r,i)=>recipeCard(r,recipePage*size+i+1)).join('')}</div><div class="pagination"><button class="btn btn-small" data-page="${recipePage-1}" ${recipePage===0?'disabled':''}>← Anterior</button><span>HOJA ${recipePage+1} DE ${Math.ceil(list.length/size)}</span><button class="btn btn-small" data-page="${recipePage+1}" ${(recipePage+1)*size>=list.length?'disabled':''}>Siguiente →</button></div>`:'<div class="empty-state"><h3>Ese plano no está en este cajón.</h3><p>Prueba el nombre en inglés o cambia de categoría o mod.</p><button class="btn mt" data-clear-filters>Abrir todo el archivo</button></div>'}</div></div><div class="catalog-footnote"><span>ⓘ</span><p>Recetas de las versiones del pack 8.1. Las condiciones especiales se muestran en cada plano; JEI confirma la receta activa de tu servidor.</p><button class="btn btn-text" data-view="sources">Fuentes ↗</button></div>`;}''')
replace_fn('recipeCard', '''function recipeCard(r,index=1){return `<article class="recipe-card blueprint-sheet"><div class="recipe-sheet-meta"><span>PL. ${String(index).padStart(3,'0')}</span><span>${esc(catalogName(r.source.modId))}</span></div><button class="recipe-object" data-recipe="${esc(r.id)}" aria-label="Abrir receta de ${esc(name(r.output.id))}"><span class="object-crosshair" aria-hidden="true"></span>${icon(r.output.id)}<span class="object-measure" aria-hidden="true">${fmt(r.output.count)} ${r.output.kind==='fluid'?'mB':'u.'}</span></button><h3>${esc(name(r.output.id))}</h3><p class="recipe-operation">${esc(process(r.type))}${r.calculatorEligible===false?' · condiciones especiales':''}</p><div class="recipe-parts"><span>MATERIALES</span><div>${r.ingredients.slice(0,4).map(i=>{const item=engine.resolve(i,state.selections);return `<span class="part-preview" title="${esc(name(item.id))} · ${fmt(i.count)}">${icon(item.id)}<b>${fmt(i.count)}</b></span>`;}).join('')}${r.ingredients.length>4?`<small>+${r.ingredients.length-4}</small>`:''}</div></div><div class="recipe-meta"><span class="pill-count">${r.output.chance<1?fmt(r.output.chance*100)+' % de éxito':'VER DESPIECE'}</span><button class="btn btn-text" data-recipe="${esc(r.id)}">Desplegar plano ↗</button></div></article>`;}''')
